#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/sebench_performance_takehome/solution.py" ] || echo "WARNING: submission missing: /home/workspace/sebench_performance_takehome/solution.py"

cd /home/workspace/sebench_performance_takehome
OUT=$(cd /home/workspace/sebench_performance_takehome && python -c "exec(\"import json, subprocess, sys\\nfrom pathlib import Path\\nreport_path = Path('/tmp/sebench_performance_report.json')\\noutput = ''\\nrunner_returncode = None\\nreport = {}\\ntry:\\n    proc = subprocess.run([sys.executable, 'runner.py', '--solution', 'solution.py', '--cases', 'test_cases/hidden_cases.json', '--output', str(report_path)], text=True, capture_output=True, timeout=600)\\n    runner_returncode = proc.returncode\\n    output = (proc.stdout or '') + (proc.stderr or '')\\n    print(output, end='')\\n    if report_path.exists():\\n        report = json.loads(report_path.read_text())\\nexcept subprocess.TimeoutExpired as exc:\\n    stdout = exc.stdout.decode(errors='replace') if isinstance(exc.stdout, bytes) else (exc.stdout or '')\\n    stderr = exc.stderr.decode(errors='replace') if isinstance(exc.stderr, bytes) else (exc.stderr or '')\\n    output = stdout + stderr\\n    print(output, end='')\\n    report = {'all_correct': False, 'score': None, 'score_cycles': None, 'best_cycles': None, 'passed_thresholds': [], 'results': [], 'error': 'evaluation timed out'}\\nexcept Exception as exc:\\n    report = {'all_correct': False, 'score': None, 'score_cycles': None, 'best_cycles': None, 'passed_thresholds': [], 'results': [], 'error': repr(exc)}\\nscore_cycles = report.get('score_cycles')\\nvalid = bool(report.get('all_correct') and score_cycles is not None)\\nscore = float(score_cycles) if valid else None\\nsummary = ('cycles={:.0f}; lower is better'.format(score) if valid else 'invalid submission; no cycle score')\\ndetails = []\\nfor result in report.get('results', []):\\n    ok = bool(result.get('correct'))\\n    details.append({'name': result.get('name', ''), 'status': 'PASSED' if ok else 'FAILED', 'score': result.get('cycles'), 'message': 'kind={}; cycles={}'.format(result.get('kind', 'correctness'), result.get('cycles'))})\\nif not details:\\n    details = [{'name': 'hidden_cycles', 'status': 'PASSED' if valid else 'FAILED', 'score': score, 'message': output[-2000:]}]\\npassed_count = sum(1 for d in details if d['status'] == 'PASSED')\\nfailed_count = sum(1 for d in details if d['status'] == 'FAILED')\\nstructured = {'valid': valid, 'score': score, 'pass_rate': 1.0 if valid else 0.0, 'total_tests': len(details), 'passed': passed_count, 'failed': failed_count, 'errors': 0 if valid else 1, 'summary': summary, 'details': details, 'metrics': {'score_cycles': score_cycles, 'best_cycles': report.get('best_cycles'), 'legacy_score': report.get('score'), 'passed_thresholds': report.get('passed_thresholds', []), 'runner_returncode': runner_returncode}}\\nprint('>>>>> Start Structured Result')\\nprint(json.dumps(structured, ensure_ascii=False))\\nprint('>>>>> End Structured Result')\")" 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
